insert into public.universities
  (id, sort, short, zh, en, city_zh, city_en, tagline_zh, tagline_en, note_zh, note_en, official_url, color, photo, photo_credit, hero_dish_id) values
  ('cityu', 1, 'CityU', '香港城市大學', 'City University of Hong Kong', '香港', 'Hong Kong', '城大覓食指南', 'CityU Canteen Guide', 'AC1 官方菜單已完整收錄；AC2／AC3 為代表性菜品，陸續補充。', 'AC1''s official menu is fully listed; AC2/AC3 entries are representative and growing.', 'https://www.cityu.edu.hk/zh-hk/directories/catering', 'ac1', 'assets/uni/cityu.jpg', 'Wikimedia Commons · 香港城市大學 City University of Hong Kong - panoramio (1).jpg', 'ac1-duck-hofun'),
  ('hku', 2, 'HKU', '香港大學', 'The University of Hong Kong', '香港', 'Hong Kong', '港大搵食指南', 'HKU Canteen Guide', '兩間食堂的菜單皆擷取自港大官方點餐系統，為真實資料。', 'Both canteens are real — menus come from HKU''s official ordering system.', 'https://www.hku.hk/', 'ac4', 'assets/uni/hku.jpg', 'Wikimedia Commons · Main Building HKU 20100926 03.JPG · CC BY-SA 3.0 · Ka-Fai, So', 'hku-cym-1100030003')
insert into public.canteens (id, uni, sort, short, zh, en, bldg_zh, bldg_en, hours_zh, hours_en, fact_zh, fact_en, photo, order_url, color) values
  ('hku-cym', 'hku', 1, 'CYM', 'CYM 食堂', 'CYM Canteen', '莊月明文娛中心 4 樓', '4/F, Chong Yuet Ming Amenities Centre', '每日 07:30–21:30', 'Daily 07:30–21:30', '美心營運，全日供餐；中式客飯 21 款、蒸魚飯 $47.8 起，最貴一道 $58。', 'Run by Maxim''s, open all day; 21 Chinese set-rice dishes, steamed fish rice from $47.8, top price $58.', 'assets/hku-cym/hero.jpg', 'https://now.order.place/#/store/102858/mode/prekiosk', 'ac4'),
  ('hku-hw', 'hku', 2, 'HW', '黃克競食堂', 'Haking Wong Canteen', '黃克競樓 4 樓', '4/F, Haking Wong Building', '每日 07:30–21:00', 'Daily 07:30–21:00', '早餐與茶餐最齊的一間：茶餐 8 款、早餐 8 類，燒味單拼飯 $27.1 起。', 'The widest breakfast and tea-set range at HKU: 8 tea sets, 8 breakfast types, BBQ rice from $27.1.', 'assets/hku-hw/hero.jpg', 'https://now.order.place/#/store/12827/mode/prekiosk', 'ac6')
