-- ── 1. 結構：大學維度 ──
create table if not exists public.universities (
  id           text primary key,
  sort         int  not null default 0,
  short        text not null,
  zh           text not null,
  en           text not null,
  city_zh      text,
  city_en      text,
  tagline_zh   text,
  tagline_en   text,
  note_zh      text,
  note_en      text,
  official_url text,
  color        text,
  photo        text,
  photo_credit text,
  hero_dish_id text
);

alter table public.canteens   add column if not exists uni   text;
alter table public.canteens   add column if not exists short text;
alter table public.canteens   add column if not exists color text;
alter table public.categories add column if not exists uni      text;
alter table public.categories add column if not exists order_url text;
alter table public.dishes     add column if not exists uni   text;

create index if not exists canteens_uni_idx   on public.canteens (uni);
create index if not exists categories_uni_idx on public.categories (uni);
create index if not exists dishes_uni_idx     on public.dishes (uni);

-- 舊 CityU 資料補上 uni
update public.canteens set uni = 'cityu' where uni is null;
update public.canteens set short = upper(id) where short is null or short = '';
update public.canteens set color = id where color is null or color = '';
update public.dishes d set uni = c.uni from public.canteens c
  where d.canteen_id = c.id and d.uni is null;
update public.categories c set uni = 'cityu'
  where c.uni is null and c.id in (
    select distinct d.category from public.dishes d
    join public.canteens ct on ct.id = d.canteen_id
    where ct.uni = 'cityu' and d.category is not null
  );

-- 非保留大學的殘留（PolyU／HKBU 從未進過 DB，這裡只是保險）
delete from public.dishes where canteen_id in (select id from public.canteens where uni not in ('cityu','hku'));
delete from public.canteens where uni not in ('cityu','hku');
delete from public.categories where uni not in ('cityu','hku');

-- ── 2. RLS 與授權（新的 universities 表要自己開，SQL Editor 建表不會自動授權）──
alter table public.universities enable row level security;
drop policy if exists "universities are public" on public.universities;
create policy "universities are public"
  on public.universities for select to anon, authenticated using (true);

grant usage on schema public to anon, authenticated;
grant select on table public.universities to anon, authenticated;

-- ── 3. 大學清單（CityU + HKU）──
on conflict (id) do update set
  sort = excluded.sort, short = excluded.short, zh = excluded.zh, en = excluded.en,
  city_zh = excluded.city_zh, city_en = excluded.city_en,
  tagline_zh = excluded.tagline_zh, tagline_en = excluded.tagline_en,
  note_zh = excluded.note_zh, note_en = excluded.note_en,
  official_url = excluded.official_url, color = excluded.color, photo = excluded.photo,
  photo_credit = excluded.photo_credit, hero_dish_id = excluded.hero_dish_id;

delete from public.universities where id not in ('cityu','hku');

-- ── 4. HKU 食堂（2 間）──
on conflict (id) do update set
  uni = excluded.uni, sort = excluded.sort, short = excluded.short, zh = excluded.zh, en = excluded.en,
  bldg_zh = excluded.bldg_zh, bldg_en = excluded.bldg_en,
  hours_zh = excluded.hours_zh, hours_en = excluded.hours_en,
  fact_zh = excluded.fact_zh, fact_en = excluded.fact_en,
  photo = excluded.photo, order_url = excluded.order_url, color = excluded.color;

-- ── 5. HKU 分類（60 個）──
on conflict (id) do update set
  uni = excluded.uni, sort = excluded.sort, zh = excluded.zh, en = excluded.en,
  meal = excluded.meal, order_url = excluded.order_url;

-- ── 6. HKU 菜品（297 道）──
on conflict (id) do update set
  uni = excluded.uni, canteen_id = excluded.canteen_id, category = excluded.category,
  zh = excluded.zh, en = excluded.en, price = excluded.price, photo = excluded.photo,
  desc_zh = excluded.desc_zh, desc_en = excluded.desc_en, tags = excluded.tags,
  available = excluded.available, sort = excluded.sort;

-- ── 7. 抽籤黑名單：飲品不是一餐的答案 ──
on conflict (kind, value) do nothing;

-- ── 8. 收尾檢查 ──
select 'universities' as t, count(*) from public.universities
union all select 'canteens', count(*) from public.canteens
union all select 'categories', count(*) from public.categories
union all select 'dishes', count(*) from public.dishes
union all select 'reviews', count(*) from public.reviews;
